import{_ as e,o as r,c as d,a3 as a}from"./chunks/framework.lx4Uzxpr.js";const c=JSON.parse('{"title":"嵌入式与 RTOS：截止期确定性的操作系统","description":"RTOS 的内核是按优先级抢占调度，把\\"最坏情况响应时间\\"变成可保证的量；由此推出任务划分、优先级反转、外设选型的全部规则","frontmatter":{"title":"嵌入式与 RTOS：截止期确定性的操作系统","date":"2026-10-24T00:00:00.000Z","tags":["机器人","硬件","嵌入式"],"category":"notes","description":"RTOS 的内核是按优先级抢占调度，把\\"最坏情况响应时间\\"变成可保证的量；由此推出任务划分、优先级反转、外设选型的全部规则","sidebar":false},"headers":[],"relativePath":"notes/机器人/硬件与电子/embedded-rtos.md","filePath":"notes/机器人/硬件与电子/embedded-rtos.md"}'),o={name:"notes/机器人/硬件与电子/embedded-rtos.md"};function s(n,t,i,h,l,g){return r(),d("div",null,t[0]||(t[0]=[a('<h1 id="嵌入式与-rtos" tabindex="-1">嵌入式与 RTOS <a class="header-anchor" href="#嵌入式与-rtos" aria-label="Permalink to “嵌入式与 RTOS”">​</a></h1><p><strong>一句话定义：RTOS = 以&quot;截止期确定性&quot;为第一目标的操作系统——按优先级抢占调度，保证最坏情况响应时间，而不是平均吞吐。</strong></p><h2 id="内核-为什么裸机大循环会失效" tabindex="-1">内核：为什么裸机大循环会失效 <a class="header-anchor" href="#内核-为什么裸机大循环会失效" aria-label="Permalink to “内核：为什么裸机大循环会失效”">​</a></h2><p>裸机程序的形态是 <code>while(1)</code> 依次处理各件事。当每件事的<strong>截止期</strong>不同（电流环 100 μs、CAN 收发 1 ms、状态上报 100 ms）时，大循环有致命缺陷：<strong>任何一件耗时的事都会推迟其他所有事</strong>，且推迟量不可预测。控制环的周期抖动直接变成控制误差（<a href="/notes/机器人/控制与运动生成/cascade-pid" class="term-link" title="电流环→速度环→位置环三环分层，带宽隔离原则">级联 PID</a>的离散化假设被破坏）。</p><p>RTOS 的内核动作：<strong>给每件事一个优先级，高优先级随时打断低优先级</strong>。基于优先级抢占 + 可预测的中断延迟，&quot;最坏响应时间&quot;从不可知变成可计算——这就是实时（real-time）的含义：<strong>不是快，是可预测</strong>。</p><h2 id="规则与行为" tabindex="-1">规则与行为 <a class="header-anchor" href="#规则与行为" aria-label="Permalink to “规则与行为”">​</a></h2><p><strong>任务划分规则</strong>：一个任务 = 一个频率 + 一个优先级。频率越高的任务优先级越高（截止期越紧），于是典型分层自上而下：电流/安全监测（kHz）→ 控制环（kHz）→ 通信收发（百 Hz）→ 状态上报（十 Hz）。<strong>大计算量低截止期的事（日志、遥测打包）必须放最低优先级或 DMA 后台</strong>。</p><p><strong>中断规则</strong>：中断服务程序（ISR）只做&quot;取数据、发队列、退出&quot;——任何耗时处理（协议解析、滤波）移到任务里。ISR 长是实时性破坏的头号原因。</p><p><strong>优先级反转</strong>（晦涩处，展开说）：低优先级任务 L 持有互斥锁，高优先级 H 等锁阻塞，此时中优先级 M 抢占 L 闲逛——H 实际被 M 压制，优先级次序颠倒。解法是<strong>优先级继承</strong>（L 临时抬升到 H 的级别直至放锁），FreeRTOS 的互斥锁默认支持。推论：<strong>任务间用互斥锁要克制，能用队列传递数据就别共享内存</strong>。</p><p><strong>通信外设选型</strong>：</p><table tabindex="0"><thead><tr><th>总线</th><th>拓扑</th><th>速率</th><th>多设备</th><th>机器人用途</th></tr></thead><tbody><tr><td>UART</td><td>点对点</td><td>低</td><td>—</td><td>调试口、简单模块</td></tr><tr><td>SPI</td><td>主+片选</td><td>高（十 MHz）</td><td>少</td><td>IMU、编码器、高速 ADC</td></tr><tr><td>I2C</td><td>总线</td><td>低（百 kHz–MHz）</td><td>多</td><td>低速配置类器件</td></tr><tr><td>CAN/CAN FD</td><td>多主差分</td><td>中</td><td>多、可靠</td><td>关节模组、整机内联网</td></tr></tbody></table><p>规则：<strong>高带宽反馈进 SPI，多节点骨干用 CAN</strong>；I2C 的时钟拉伸与上拉脆弱性使它只配低速场景。</p><h2 id="抽象-队列与消息——任务解耦的标准件" tabindex="-1">抽象：队列与消息——任务解耦的标准件 <a class="header-anchor" href="#抽象-队列与消息——任务解耦的标准件" aria-label="Permalink to “抽象：队列与消息——任务解耦的标准件”">​</a></h2><p>RTOS 提供的原语（任务、队列、信号量、定时器）之上的抽象是：<strong>任务之间不共享数据，只传消息</strong>（队列天然带锁、可缓存突发、天然记录先后因果）。这一步消掉了大部分锁与优先级反转问题。再往上，把&quot;控制环任务 + CAN 收发任务 + 状态机任务&quot;打包成关节固件——<a href="/notes/机器人/结构与机构/reducers" class="term-link" title="电机+减速器+双编码器+驱动器一体化，传动问题封装成选型参数">关节模组</a>的软件形态。上电即跑的实时层就位后，上层 ROS 2 节点通过 CAN/串口桥接它（见 ROS 2 体系篇），两层之间唯一的契约是消息格式与频率。</p>',14)]))}const m=e(o,[["render",s]]);export{c as __pageData,m as default};
